import{_ as i,o as u,c as t,a2 as n}from"./chunks/framework.CqpfiAoK.js";const r=JSON.parse('{"title":"Mfumo wa Haki na Mfumo wa Maamuzi","description":"","frontmatter":{},"headers":[],"relativePath":"sw/48-司法体系与裁决机制.md","filePath":"sw/48-司法体系与裁决机制.md","lastUpdated":1789183869000}'),k={name:"sw/48-司法体系与裁决机制.md"};function h(m,a,o,e,w,s){return u(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="mfumo-wa-haki-na-mfumo-wa-maamuzi" tabindex="-1">Mfumo wa Haki na Mfumo wa Maamuzi <a class="header-anchor" href="#mfumo-wa-haki-na-mfumo-wa-maamuzi" aria-label="Permalink to &quot;Mfumo wa Haki na Mfumo wa Maamuzi&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>48</td></tr><tr><td>Moduli</td><td>Mfumo wa Kisheria na Muundo wa Usimamizi</td></tr><tr><td>Maneno muhimu ya msingi</td><td>Mahakama ya Usawa, Uwezo wa Haki, Mfumo wa Maamuzi, Hukumu ya Kati ya Kabila, Uchunguzi wa Katiba</td></tr></tbody></table><h2 id="_1-nafasi-na-kanuni-za-mfumo-wa-haki" tabindex="-1">1. Nafasi na Kanuni za Mfumo wa Haki <a class="header-anchor" href="#_1-nafasi-na-kanuni-za-mfumo-wa-haki" aria-label="Permalink to &quot;1. Nafasi na Kanuni za Mfumo wa Haki&quot;">​</a></h2><p>Mfumo wa haki ni mhimili muhimu wa muundo wa usimamizi wa ustaarabu wa usawa wa nanga, sawa na mamlaka ya kisheria (Baraza la Nanga) na mamlaka ya utawala (Kamiti ya Tekelezaji ya Usawa), na inatekeleza uwezo wa hukumu kwa uhuru. 《Katiba ya Usawa》 inaweka muundo wa usimamizi wa &quot;mgawanyiko na usawa wa mamlaka tatu&quot;, na mfumo wa haki ni mstari wa mwisho wa ulinzi wa kudumisha heshima ya katiba, kulinda haki za viumbe wote, na kutatua mizozo ya kijamii.</p><p>Mfumo wa haki wa Hengyuanzhou unaweka kanuni zifuatazo za msingi:</p><table tabindex="0"><thead><tr><th>Kanuni</th><th>Maudhui</th></tr></thead><tbody><tr><td>Kanuni ya Uwezo wa Haki</td><td>Mahakama zinatekeleza uwezo wa hukumu kwa uhuru kulingana na sheria, bila kuingiliwa na mashirika ya utawala, mashirika ya kijamii, na watu binafsi</td></tr><tr><td>Kanuni ya Haki ya Haki</td><td>Shughuli za hukumu zinategemea ukweli na zinatumia sheria kama kipimo, na zinahakikisha haki ya utaratibu na haki ya kisukari</td></tr><tr><td>Kanuni ya Ufumbuzi wa Haki</td><td>Shughuli za hukumu zinafanyika kwa uwazi kulingana na sheria, na hati za hukumu zinachapishwa, na zinapokea ufuatiliaji wa kijamii</td></tr><tr><td>Kanuni ya Usawa wa Kabila zote</td><td>Viumbe vyote vina sawa mbele ya haki, na utekelezaji wa sheria hautofautishi kabila, kiwango cha mazoezi, au asili</td></tr><tr><td>Kanuni ya Urahisi wa Haki</td><td>Huduma za haki lazima ziwe rahisi kwa viumbe vote, kupunguza gharama za mashtaka, na kutoa njia nyingi za kutatua mizozo</td></tr><tr><td>Kanuni ya Hukumu ya Mwisho</td><td>Inatekelezwa mfumo wa viwango viwili kama kiwango cha mwisho, na hukumu ya mwisho ina athari ya kumaliza, na inadumisha mamlaka ya haki</td></tr></tbody></table><h2 id="_2-mfumo-wa-shirikisho-la-mahakama" tabindex="-1">2. Mfumo wa Shirikisho la Mahakama <a class="header-anchor" href="#_2-mfumo-wa-shirikisho-la-mahakama" aria-label="Permalink to &quot;2. Mfumo wa Shirikisho la Mahakama&quot;">​</a></h2><p>Mfumo wa shirikisho la mahakama wa ustaarabu wa usawa wa nanga umegawanyika katika viwango vinne, na unatekelezwa mfumo wa viwango viwili kama kiwango cha mwisho:</p><table tabindex="0"><thead><tr><th>Kiwango</th><th>Jina la Mahakama</th><th>Eneo la Mamlaka</th><th>Kazi Kuu</th></tr></thead><tbody><tr><td>Kiwango cha kwanza</td><td>Mahakama ya Msingi ya Usawa</td><td>Kaunti/Plano Ndogo</td><td>Inahukumu mashtaka ya kiraia, ya jinai, ya utawala kwa kiwango cha kwanza, na inatatuia mizozo rahisi</td></tr><tr><td>Kiwango cha pili</td><td>Mahakama ya Mkoa wa Usawa</td><td>Mji/Mkoa/Plano wa Kati</td><td>Inahukumu mashtaka makubwa ya kiwango cha kwanza na mashtaka ya rufaa dhidi ya hukumu ya mahakama ya msingi</td></tr><tr><td>Kiwango cha tatu</td><td>Mahakama ya Plano ya Usawa</td><td>Plano Kubwa/Kikundi cha Plano</td><td>Inahukumu mashtaka makubwa sana ya kiwango cha kwanza na mashtaka ya rufaa dhidi ya hukumu ya mahakama ya mkoa</td></tr><tr><td>Kiwango cha nne</td><td>Mahakama Kuu ya Usawa</td><td>Ulimwengu wote</td><td>Inahukumu mashtaka ya katiba ya kiwango cha kwanza, mashtaka ya rufaa dhidi ya hukumu ya mahakama ya plano, na uchunguzi wa katiba</td></tr></tbody></table><p>Zaidi ya hayo, mahakama maalum zinaanzishwa kulingana na mahitaji:</p><ul><li><strong>Mahakama ya Mizozo ya Mazoezi</strong>: Inahukumu maalum mashtaka ya mizozo ya rasilimali za mazoezi, fidia za uharibifu wa mazoezi, mizozo ya maadili ya mazoezi, n.k.</li><li><strong>Mahakama ya Kati ya Kabila</strong>: Inahukumu maalum mashtaka ya mizozo inayohusisha makabila tofauti, na ina wanaohukumu wa kila kabila.</li><li><strong>Mahakama ya Biashara ya Plano</strong>: Inahukumu maalum mashtaka ya mizozo ya biashara ya kati ya plano na mashtaka ya kupinga ushirikiano.</li><li><strong>Mahakama ya Viumbe vya Aje</strong>: Inahukumu maalum mashtaka maalum inayohusisha viumbe vya aje, nishati ya aje, na miili ya uingizwaji wa giza.</li></ul><h2 id="_3-mfumo-wa-wanaohukumu" tabindex="-1">3. Mfumo wa Wanaohukumu <a class="header-anchor" href="#_3-mfumo-wa-wanaohukumu" aria-label="Permalink to &quot;3. Mfumo wa Wanaohukumu&quot;">​</a></h2><p>Wanaohukumu ni wanaotekeleza mamlaka ya haki, na ubora wao na uhuru wao wanahusiana moja kwa moja na haki ya haki:</p><ol><li><strong>Masharti ya Utekelezaji wa Wanaohukumu</strong>: Wanaohukumu lazima wawe na tabia nzuri, maarifa ya kisheria thabiti, na uzoefu wa vitendo uliojaa, na wanaohukumu wa kabila la nje pia lazima wawe na ujuzi wa utamaduni na tabia za kimaumbile za kabila yao wenyewe.</li><li><strong>Mchakato wa Uteuzi wa Wanaohukumu</strong>: Wanaohukumu wanateuliwa na kamiti ya uteuzi ya wanaohukumu ya uhuru na wanaagizwa na Baraza la Nanga, na kuhakikisha haki na ufundi wa mchakato wa uteuzi.</li><li><strong>Hakikisho ya Kitambulisho cha Wanaohukumu</strong>: Wanaohukumu hawawezi kufukuzwa, kupunguzwa cheo, kufukuzwa kazi, au kupigwa faini bila sababu ya kisheria na bila kupitia mchakato wa kisheria, na kuhakikisha wanaohukumu wanaweza kuhukumu kwa uhuru.</li><li><strong>Mfumo wa Kujitenga kwa Wanaohukumu</strong>: Mwanaohukumu ambaye ana uhusiano wa maslahi na pande za mashtaka au matokeo ya mashtaka lazima ajitenge, na hawezi kushiriki katika hukumu ya mashtaka.</li><li><strong>Mfumo wa Adhabu ya Wanaohukumu</strong>: Mwanaohukumu anayefanya tabia za ufisadi, rushwa, udanganyifu, hukumu isiyo ya haki, n.k., atapigwa faini kulingana na sheria, na yule anayejenga uhalishi atafuatiliwa wajibu wa jinai.</li><li><strong>Kiasi cha Wanaohukumu wa Kabila la Nje</strong>: Mahakama kwa viwango vyote lazima ziwe na wanaohukumu wa kabila la nje kwa uwiano fulani, na kuhakikisha hukumu inaweza kuzingatia utamaduni na maarifa ya kisheria ya kila kabila.</li></ol><h2 id="_4-mchakato-wa-mashtaka" tabindex="-1">4. Mchakato wa Mashtaka <a class="header-anchor" href="#_4-mchakato-wa-mashtaka" aria-label="Permalink to &quot;4. Mchakato wa Mashtaka&quot;">​</a></h2><h3 id="_1-mchakato-wa-mashtaka-ya-kiraia" tabindex="-1">(1) Mchakato wa Mashtaka ya Kiraia <a class="header-anchor" href="#_1-mchakato-wa-mashtaka-ya-kiraia" aria-label="Permalink to &quot;(1) Mchakato wa Mashtaka ya Kiraia&quot;">​</a></h3><p>Mashtaka ya kiraia inatekelezwa kanuni ya &quot;hakuna mashtaka hakuna hukumu&quot;, na mchakato unajumuisha:</p><ol><li><strong>Mashtaka na Kupokelewa</strong>: Mwenye mashtaka anawasilisha hati ya mashtaka kwa mahakama yenye mamlaka, na mahakama inaamua baada ya uchunguzi ikiwa itapokea au hapana.</li><li><strong>Maandalizi Kabla ya Hukumu</strong>: Mahakama inatuma nakala ya hati ya mashtaka kwa mwenye mashtaka, inapanga ubadilishaji wa ushahidi, na inabainisha pointi za mizozo.</li><li><strong>Hukumu kwenye Mahakama</strong>: Uchunguzi wa mahakama, mjadala wa mahakama, taarifa ya mwisho ya pande, na upatanisho unapendelewa.</li><li><strong>Hukumu na Utekelezaji</strong>: Mahakama inatoa hukumu kulingana na sheria, na pande ambazo haziridhiki zinaweza kuomba rufaa ndani ya muda wa kisheria. Hukumu yenye ufanisi inatekelezwa kwa kulazimishwa na shirika la utekelezaji.</li></ol><h3 id="_2-mchakato-wa-mashtaka-ya-jinai" tabindex="-1">(2) Mchakato wa Mashtaka ya Jinai <a class="header-anchor" href="#_2-mchakato-wa-mashtaka-ya-jinai" aria-label="Permalink to &quot;(2) Mchakato wa Mashtaka ya Jinai&quot;">​</a></h3><p>Mashtaka ya jinai inatekelezwa kanuni ya &quot;dhana ya kutokuwa na hatia&quot;, na mchakato unajumuisha:</p><ol><li><strong>Usajili na Uchunguzi</strong>: Shirika la uchunguzi linaandikisha na kuchunguza tabia ya jinai, likikusanya ushahidi, na kuchukua hatua za kulazimisha.</li><li><strong>Uchunguzi na Mashtaka</strong>: Shirika la mashtaka linachunguza matokeo ya uchunguzi, na inaamua ikiwa itatoa mashtaka ya umma au hapana.</li><li><strong>Hukumu</strong>: Mahakama inafanya hukumu kwenye mahakama, na pande za mashtaka na ulinzi zinawasilisha na kuchunguza ushahidi, na mahakama inatoa hukumu kulingana na sheria.</li><li><strong>Utekelezaji</strong>: Hukumu yenye ufanisi inatekelezwa na shirika la utekelezaji, ikiwa ni pamoja na utekelezaji wa adhabu na utekelezaji wa fidia ya kiraia inayofuata.</li></ol><h3 id="_3-mchakato-wa-mashtaka-ya-utawala" tabindex="-1">(3) Mchakato wa Mashtaka ya Utawala <a class="header-anchor" href="#_3-mchakato-wa-mashtaka-ya-utawala" aria-label="Permalink to &quot;(3) Mchakato wa Mashtaka ya Utawala&quot;">​</a></h3><p>Raia, shirika la kisheria, au shirika lingine linalofikiria kuwa tabia ya utawala ya shirika la utawala imevunja haki zake za kisheria, lina haki ya kuwasilisha mashtaka ya utawala kwa mahakama. Mashtaka ya utawala inatekelezwa &quot;kubadilisha mzigo wa ushahidi&quot;, na shirika la utawala linalotajwa lazima libebe mzigo wa ushahidi kuhusu halali ya tabia yake ya utawala.</p><h3 id="_4-mchakato-wa-mashtaka-ya-katiba" tabindex="-1">(4) Mchakato wa Mashtaka ya Katiba <a class="header-anchor" href="#_4-mchakato-wa-mashtaka-ya-katiba" aria-label="Permalink to &quot;(4) Mchakato wa Mashtaka ya Katiba&quot;">​</a></h3><p>Viumbe vote vinavofikiria kuwa haki zao za msingi za katiba zimevunjwa, na vimetumia njia zote za msaada, vinaweza moja kwa moja kuwasilisha mashtaka ya katiba kwa Mahakama Kuu ya Usawa kulingana na Katiba. Mashtaka ya katiba ni njia ya mwisho ya msaada ya kulinda haki za katiba.</p><h2 id="_5-mfumo-wa-kutatua-mizozo-kwa-njia-nyingi" tabindex="-1">5. Mfumo wa Kutatua Mizozo kwa Njia Nyingi <a class="header-anchor" href="#_5-mfumo-wa-kutatua-mizozo-kwa-njia-nyingi" aria-label="Permalink to &quot;5. Mfumo wa Kutatua Mizozo kwa Njia Nyingi&quot;">​</a></h2><p>Ili kupunguza mzigo wa haki na kuboresha ufanisi wa kutatua mizozo, Serikali inaweka mfumo wa kutatua mizozo kwa njia nyingi:</p><table tabindex="0"><thead><tr><th>Mfumo</th><th>Eneo la Utekelezaji</th><th>Athari</th></tr></thead><tbody><tr><td>Mazungumzo na Makubaliano</td><td>Mizozo yote ya kiraia</td><td>Pande zinazitikia kwa hiari, na hazina uwezo wa utekelezaji wa kulazimisha</td></tr><tr><td>Upatanisho wa Wananchi</td><td>Mizozo ya watu, mizozo ya majirani</td><td>Makubaliano ya upatanisho yana uwezo wa utekelezaji wa kulazimisha baada ya uthibitisho wa kisheria kutoka mahakama</td></tr><tr><td>Upatanisho wa Utawala</td><td>Mizozo ya utawala, mizozo ya fidia ya kiraia</td><td>Makubaliano ya upatanisho yana athari ya mkataba</td></tr><tr><td>Tahakimu</td><td>Mizozo ya biashara, mizozo ya kazi</td><td>Hukumu ya tahakimu ina uwezo wa utekelezaji wa kulazimisha, na tahakimu moja ni ya mwisho</td></tr><tr><td>Hukumu ya Haki</td><td>Mizozo yote</td><td>Hukumu ya mwisho ina uwezo wa utekelezaji wa kulazimisha wa mwisho</td></tr></tbody></table><p>Serikali inashawishi pande kuzipendelea kutatua mizozo kwa njia isiyo ya mashtaka, na mahakama pia zinafaa kufanya upatanisho wakati wa mchakato wa mashtaka.</p><h2 id="_6-mfumo-wa-uchunguzi-wa-katiba" tabindex="-1">6. Mfumo wa Uchunguzi wa Katiba <a class="header-anchor" href="#_6-mfumo-wa-uchunguzi-wa-katiba" aria-label="Permalink to &quot;6. Mfumo wa Uchunguzi wa Katiba&quot;">​</a></h2><p>Uchunguzi wa katiba ni mfumo muhimu kwa mfumo wa haki kudumisha mamlaka ya katiba:</p><ol><li><strong>Mada ya Uchunguzi</strong>: Mahakama Kuu ya Usawa ni mada pekee ya uchunguzi wa katiba, na inaanzisha chumba cha hukumu ya katiba kinachohusika maalum na uchunguzi wa katiba.</li><li><strong>Eneo la Uchunguzi</strong>: Sheria, kanuni za utawala, kanuni za mkoa, kanuni za kujitegemea, tafsiri za haki, na hati zingine za kanuni zinavunja katiba au hapana.</li><li><strong>Kuanza Uchunguzi</strong>: Inaweza kuanzishwa kwa hiari na mahakama wakati wa hukumu ya mashtaka, au kwa ombi la uchunguzi lililotolewa na viumbe vote, mashirika, au mashirika ya serikali.</li><li><strong>Athari ya Uchunguzi</strong>: Hati za kanuni zilizochunguzwa na kuthibitishwa kuwa zinavunja katiba, hazina ufanisi tangu siku ya kuchapishwa, na hazitumiwi tena kama msingi wa hukumu.</li><li><strong>Kiwango cha Uchunguzi</strong>: Kutingemea maandishi ya katiba na kanuni za katiba, na kuzingatia utulivu wa mfumo wa kisheria na uwezo wa kuzingatia katiba.</li></ol><h2 id="_7-hakikisho-na-ufuatiliaji-wa-haki" tabindex="-1">7. Hakikisho na Ufuatiliaji wa Haki <a class="header-anchor" href="#_7-hakikisho-na-ufuatiliaji-wa-haki" aria-label="Permalink to &quot;7. Hakikisho na Ufuatiliaji wa Haki&quot;">​</a></h2><ul><li><strong>Hakikisho ya Bajeti ya Haki</strong>: Bajeti ya mahakama inahakikishwa tofauti kutoka kwa akiba ya umma, na haikontroliki na mashirika ya utawala ya mkoa, na inahakikisha msingi wa kiuchumi wa uwezo wa haki.</li><li><strong>Teknolojia ya Habari za Haki</strong>: Kutumia teknolojia ya mawasiliano ya kati ya plano kuanzisha mfumo wa habari za haki,实现 teknolojia ya habari ya mchakato wote wa usajili, hukumu, na utekelezaji, na kuboresha ufanisi wa haki.</li><li><strong>Ufuatiliaji wa Haki</strong>: Kamiti ya Ufuatiliaji ya Nanga inafuatilia shughuli za haki, na umma na vyombo vya habari vinaweza kufanya ufuatiliaji wa maoni ya umma juu ya shughuli za haki, lakini hawawezi kuingilia uwezo wa hukumu.</li><li><strong>Msaada wa Haki</strong>: Kutoa msaada wa kisheria na kupunguza au kusitisha gharama za mashtaka kwa pande zenye shida ya kiuchumi, na kuhakikisha hawapotezi fursa ya msaada wa haki kwa sababu ya kiuchumi.</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Mfumo wa haki ni hakikisho la mwisho la utawala wa sheria wa ustaarabu wa usawa wa nanga. Kupitia kuanzisha mfumo wa mahakama ya viwango vinne, kutekeleza uwezo wa haki, kuanzisha mfumo wa kutatua mizozo kwa njia nyingi na mfumo wa uchunguzi wa katiba, inahakikisha sheria inatekelezwa kwa haki, haki za viumbe vote zinapewa msaada kwa ufanisi, na inaimarisha mstari wa ulinzi wa sheria kwa maendeleo ya pamoja ya kabila zote.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Kanuni za Msingi za Katiba ya Usawa)</li><li>49-治理框架与权力制衡 (Muundo wa Usimamizi na Usawa wa Mamlaka)</li><li>58-双魂伦理准则 (Kanuni za Maadili ya Roho Mbili)</li><li>03-共生文明宪章 (Hati ya Nguvu za Ustaarabu wa Usawa)</li></ul>',38)])])}const z=i(k,[["render",h]]);export{r as __pageData,z as default};
